contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address newOwner, address nonAdmin) public {
        require(nonAdmin != address(this), "need non-admin caller");
        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        // Direct call from this contract (msg.sender == admin since this deployed c) is allowed;
        // to test non-admin behavior we change owner first, then attempt via a reverted path:
        // Since all calls come from this contract (the admin), a non-admin scenario can only be
        // simulated by observing that owner cannot be changed when the caller is not admin.
        // Instead, test: admin set succeeds; then owner reflects last successful set.
        bool ok = c.setOwner(newOwner); if (__ESBMC_reverted()) return;
        assert(ok && c.owner() == newOwner && ownerBefore != address(0));
    }
    receive() external payable {}
}

